let partyPlayed=false,partyContext=null,partyAttempting=false;
async function playPartySound(){
 if(partyAttempting)return;const box=document.querySelector('#celebration');if(!box||box.hidden||!box.dataset.newsId)return;
 const id=box.dataset.newsId;if(partyPlayed===id)return;try{if(localStorage.getItem('klippen-party-seen')===id)return;}catch{}
 const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;partyAttempting=true;
 try{
  if(!partyContext){partyContext=new Audio();partyContext.addEventListener('statechange',()=>{if(partyContext.state==='running')playPartySound();});}const ctx=partyContext;
  if(ctx.state!=='running'){ctx.resume().catch(()=>{});if(ctx.state!=='running')return;}
  if(box.dataset.newsId!==id||box.hidden)return;
  partyPlayed=id;try{localStorage.setItem('klippen-party-seen',id);}catch{}
  [523.25,659.25,783.99,1046.5,1318.5,1567.98,2093].forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=i<4?'triangle':'sine';o.frequency.value=freq;const t=ctx.currentTime+i*.12;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.085,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.36);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.37);});
 }catch{}finally{partyAttempting=false;}
}
